/** The typed body of each operation's success replies (every 2xx schema it documents). */
export interface OperationSuccessReplies {
  readonly ListAgencies: ListAgenciesReply;
  readonly CreateAgency: CreateAgencyCompleted;
  readonly GetAgency: GetAgencyReply;
  readonly ListClients: ListClientsReply;
  readonly CreateClient: CreateClientCompleted;
  readonly ListMembers: ListMembersReply;
  readonly ArchiveClient: ArchiveClientCompleted;
  readonly CreateProject: CreateProjectCompleted;
  readonly ApprovePlan: ApprovePlanCompleted;
  readonly RevisePlan: RevisePlanCompleted;
  readonly WithdrawApproval: WithdrawApprovalCompleted;
  readonly GetProject: GetProjectReply;
  readonly getLiveness: getLivenessResponse200;
  readonly getReadiness: getReadinessResponse200;
}

export type SuccessReply<Id extends OperationId> = OperationSuccessReplies[Id];

export function operationById(operationId: string): OperationDescriptor | undefined {
  return Object.hasOwn(OPERATIONS, operationId) ? OPERATIONS[operationId as OperationId] : undefined;
}
